// Written to match the behavior of:
//   GDAL v3.13.2:
//     ogr/ogr_srs_api.h (OSRGetCRSInfoListFromDatabase)
//   PROJ 9.8.1:
//     src/iso19111/c_api.cpp (proj_get_crs_info_list_from_database)
// No code is translated from these sources.

//! The registry CRSs terrio resolves, listed for searchable CRS pickers: [`list_crs`].
//!
//! The catalog (`data/crs_catalog.tsv.zst`, generated by `scripts/gen_crs_catalog.py`) holds what
//! `OSRGetCRSInfoListFromDatabase` gives for each EPSG, ESRI and IAU_2015 CRS of terrio's own
//! tables: its name, kind, deprecation, area of use, projection method and celestial body. It is
//! decompressed on first use, without the definitions of the CRSs.

use serde::Serialize;
use std::sync::OnceLock;

static DATA: &[u8] = include_bytes!("../data/crs_catalog.tsv.zst");

/// The version of the EPSG Geodetic Parameter Dataset whose CRSs terrio carries and
/// [`list_crs`] lists: that of PROJ 9.8.1's database.
pub const EPSG_VERSION: &str = "v12.029";

/// The authorities [`list_crs`] lists, in the order it lists them.
pub const AUTHORITIES: [&str; 3] = ["EPSG", "ESRI", "IAU_2015"];

/// Checks the authorities a query names, whatever their case: each must be one of
/// [`AUTHORITIES`]. The bindings and `terrio list-crs` refuse another, where [`list_crs`] lists
/// nothing for it.
pub fn check_authorities(authorities: &[String]) -> crate::Result<()> {
    match authorities.iter().find(|a| !AUTHORITIES.iter().any(|x| x.eq_ignore_ascii_case(a.trim()))) {
        Some(a) => Err(crate::Error::InvalidArgument(format!("unknown CRS authority {a:?}: expected one of {}", AUTHORITIES.join(", ")))),
        None => Ok(()),
    }
}

/// The kind of a CRS, as GDAL's `OSRCRSType` gives it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize)]
#[non_exhaustive]
pub enum CrsKind {
    /// A geographic 2D CRS (`EPSG:4326`).
    #[serde(rename = "geographic_2d")]
    Geographic2D,
    /// A geographic 3D CRS (`EPSG:4979`).
    #[serde(rename = "geographic_3d")]
    Geographic3D,
    /// A geocentric CRS (`EPSG:4978`).
    #[serde(rename = "geocentric")]
    Geocentric,
    /// A projected CRS (`EPSG:3577`).
    #[serde(rename = "projected")]
    Projected,
    /// A vertical CRS (`EPSG:5773`).
    #[serde(rename = "vertical")]
    Vertical,
    /// A compound CRS (`EPSG:9518`).
    #[serde(rename = "compound")]
    Compound,
    /// Another kind of CRS: a planetocentric CRS with spherical coordinates
    /// (`IAU_2015:49902`).
    #[serde(rename = "other")]
    Other,
}

impl CrsKind {
    /// Every kind, in order.
    pub const ALL: [CrsKind; 7] = [
        CrsKind::Geographic2D,
        CrsKind::Geographic3D,
        CrsKind::Geocentric,
        CrsKind::Projected,
        CrsKind::Vertical,
        CrsKind::Compound,
        CrsKind::Other,
    ];

    /// The kind's name: `geographic_2d`, `geographic_3d`, `geocentric`, `projected`,
    /// `vertical`, `compound` or `other`.
    pub fn as_str(self) -> &'static str {
        match self {
            CrsKind::Geographic2D => "geographic_2d",
            CrsKind::Geographic3D => "geographic_3d",
            CrsKind::Geocentric => "geocentric",
            CrsKind::Projected => "projected",
            CrsKind::Vertical => "vertical",
            CrsKind::Compound => "compound",
            CrsKind::Other => "other",
        }
    }

    fn from_catalog(code: &str) -> Option<Self> {
        Some(match code {
            "2" => CrsKind::Geographic2D,
            "3" => CrsKind::Geographic3D,
            "g" => CrsKind::Geocentric,
            "p" => CrsKind::Projected,
            "v" => CrsKind::Vertical,
            "k" => CrsKind::Compound,
            "o" => CrsKind::Other,
            _ => return None,
        })
    }
}

impl std::fmt::Display for CrsKind {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

impl std::str::FromStr for CrsKind {
    type Err = crate::Error;

    /// Parses a kind's name ([`CrsKind::as_str`]), whatever its case.
    fn from_str(s: &str) -> crate::Result<Self> {
        CrsKind::ALL.into_iter().find(|k| k.as_str().eq_ignore_ascii_case(s.trim())).ok_or_else(|| {
            let names: Vec<&str> = CrsKind::ALL.iter().map(|k| k.as_str()).collect();
            crate::Error::InvalidArgument(format!("unknown CRS kind {s:?}: expected one of {}", names.join(", ")))
        })
    }
}

/// A CRS of the registries terrio carries, as [`list_crs`] lists it.
///
/// `SpatialRef::parse` resolves `"{authority}:{code}"` to it (`SpatialRef::from_epsg`,
/// `from_esri` or `from_iau` take the code), a deprecated EPSG code to the definition of its
/// replacement, as GDAL does.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[non_exhaustive]
pub struct CrsEntry {
    /// The authority: `EPSG`, `ESRI` or `IAU_2015`.
    pub authority: &'static str,
    /// The code.
    pub code: u32,
    /// The name (`GDA94 / Australian Albers`).
    pub name: String,
    pub kind: CrsKind,
    /// Whether the authority has deprecated it.
    pub deprecated: bool,
    /// The name of its area of use (`Australia - Australian Capital Territory; ...`).
    pub area_name: Option<String>,
    /// The bounding box of its area of use: west, south, east and north, in degrees (west is
    /// greater than east for an area across the antimeridian).
    pub bounds: Option<[f64; 4]>,
    /// The method of its projection (`Albers Equal Area`), for a projected CRS.
    pub projection_method: Option<String>,
    /// The celestial body it is on (`Earth`, `Mars`).
    pub celestial_body: Option<String>,
}

impl CrsEntry {
    /// The authority and code as `SpatialRef::parse` reads them: `EPSG:3577`.
    pub fn authority_code(&self) -> String {
        format!("{}:{}", self.authority, self.code)
    }
}

/// Which CRSs [`list_crs`] lists. The default lists every current CRS.
///
/// ```
/// use terrio_crs::{CrsKind, CrsQuery, list_crs};
///
/// let query = CrsQuery {
///     authorities: vec!["EPSG".into()],
///     kinds: vec![CrsKind::Projected],
///     text: Some("australian albers".into()),
///     ..Default::default()
/// };
/// let found = list_crs(&query);
/// assert!(found.iter().any(|e| e.code == 3577));
/// ```
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct CrsQuery {
    /// The authorities to list (`EPSG`, `ESRI`, `IAU_2015`), whatever their case; every
    /// authority when empty. An authority terrio has no registry of lists nothing.
    pub authorities: Vec<String>,
    /// The kinds to list; every kind when empty.
    pub kinds: Vec<CrsKind>,
    /// Whether to list deprecated CRSs too.
    pub include_deprecated: bool,
    /// Words the CRS must match, separated by whitespace and whatever their case: each must be
    /// in its name, or begin its code or its `authority:code`. `Albers`, `3577`, `EPSG:3577`,
    /// `gda94 albers` and `epsg albers` all match EPSG:3577. Every CRS matches no words.
    pub text: Option<String>,
}

/// A CRS of the catalog.
struct Record {
    authority: &'static str,
    code: u32,
    code_text: String,
    /// `authority:code`, in lower case.
    key: String,
    kind: CrsKind,
    deprecated: bool,
    area: Option<usize>,
    method: Option<usize>,
    body: Option<usize>,
    name: String,
    /// The name, in lower case.
    search: String,
    /// Whether terrio resolves its code, checked on first use.
    resolves: OnceLock<bool>,
}

struct Catalog {
    /// Areas of use: their bounds, when known, and name.
    areas: Vec<(Option<[f64; 4]>, String)>,
    methods: Vec<String>,
    bodies: Vec<String>,
    records: Vec<Record>,
}

fn catalog() -> &'static Catalog {
    static CATALOG: OnceLock<Catalog> = OnceLock::new();
    CATALOG.get_or_init(|| parse(&crate::epsg::decompress(DATA)))
}

/// A text of the catalog, whose backslashes, tabs, line feeds and carriage returns are escaped
/// (`\\`, `\t`, `\n`, `\r`): two EPSG area names end with a line feed, as in PROJ's database.
fn unescape(text: &str) -> String {
    if !text.contains('\\') {
        return text.to_string();
    }
    let mut out = String::with_capacity(text.len());
    let mut chars = text.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            out.push(c);
            continue;
        }
        out.push(match chars.next() {
            Some('t') => '\t',
            Some('n') => '\n',
            Some('r') => '\r',
            Some(other) => other,
            None => '\\',
        });
    }
    out
}

fn parse(text: &str) -> Catalog {
    let mut c = Catalog { areas: Vec::new(), methods: Vec::new(), bodies: Vec::new(), records: Vec::new() };
    // The ids of the `U`, `M` and `B` lines are their positions, in order.
    let id = |field: &str| field.parse::<usize>().ok();
    for line in text.lines() {
        let f: Vec<&str> = line.split('\t').collect();
        match f[..] {
            ["U", _, bounds, name] => {
                let b: Vec<f64> = bounds.split(',').filter_map(|v| v.parse().ok()).collect();
                c.areas.push((<[f64; 4]>::try_from(b).ok(), unescape(name)));
            }
            ["M", _, name] => c.methods.push(unescape(name)),
            ["B", _, name] => c.bodies.push(unescape(name)),
            ["C", authority, code, kind, flags, area, method, body, name] => {
                let (Some(authority), Ok(number), Some(kind)) =
                    (AUTHORITIES.into_iter().find(|a| *a == authority), code.parse(), CrsKind::from_catalog(kind))
                else {
                    continue;
                };
                let name = unescape(name);
                c.records.push(Record {
                    authority,
                    code: number,
                    code_text: code.to_string(),
                    key: format!("{authority}:{code}").to_lowercase(),
                    kind,
                    deprecated: flags.contains('d'),
                    area: id(area),
                    method: id(method),
                    body: id(body),
                    search: name.to_lowercase(),
                    name,
                    resolves: OnceLock::new(),
                });
            }
            _ => {}
        }
    }
    debug_assert!(!c.records.is_empty(), "the CRS catalog did not decompress");
    c
}

impl Record {
    /// Whether every word (in lower case) is in the name, or begins the code or `authority:code`.
    fn matches(&self, words: &[String]) -> bool {
        words.iter().all(|w| self.search.contains(w.as_str()) || self.code_text.starts_with(w.as_str()) || self.key.starts_with(w.as_str()))
    }

    /// Whether terrio resolves the CRS's code: always for the EPSG CRSs of the catalog, which are
    /// those of terrio's table; for the ESRI and IAU_2015 CRSs, when terrio computes their
    /// projection (in this build: `SpatialRef::from_esri` refuses the ESRI CRSs on projections
    /// that need the `wbprojection-fallback` feature, and those terrio does not compute as PROJ).
    fn resolves(&self) -> bool {
        *self.resolves.get_or_init(|| match self.authority {
            "ESRI" => crate::SpatialRef::from_esri(self.code).is_ok(),
            "IAU_2015" => crate::SpatialRef::from_iau(self.code).is_ok(),
            _ => true,
        })
    }

    fn entry(&self, c: &Catalog) -> CrsEntry {
        let area = self.area.and_then(|i| c.areas.get(i));
        CrsEntry {
            authority: self.authority,
            code: self.code,
            name: self.name.clone(),
            kind: self.kind,
            deprecated: self.deprecated,
            area_name: area.map(|(_, n)| n.clone()).filter(|n| !n.is_empty()),
            bounds: area.and_then(|(b, _)| *b),
            projection_method: self.method.and_then(|i| c.methods.get(i)).cloned(),
            celestial_body: self.body.and_then(|i| c.bodies.get(i)).cloned(),
        }
    }
}

/// The CRSs of the registries terrio carries that a query selects, by authority (EPSG, ESRI,
/// IAU_2015) and code, as GDAL's `OSRGetCRSInfoListFromDatabase` describes them (EPSG
/// [`EPSG_VERSION`], from PROJ 9.8.1's database).
///
/// Listed are the CRSs terrio resolves without network or PROJ installation: the EPSG geographic,
/// geocentric, projected, vertical and compound CRSs of its table (not engineering CRSs, compound
/// CRSs other than a horizontal and a vertical one, or the few CRSs GDAL does not import), the
/// ESRI geographic and projected CRSs whose projection terrio computes (some need the
/// `wbprojection-fallback` feature), and the IAU_2015 CRSs. `SpatialRef::parse` takes each one's
/// [`CrsEntry::authority_code`]; heights are transformed through a vertical CRS as part of a
/// compound CRS (`EPSG:4326+5773`).
///
/// ```
/// use terrio_crs::{CrsQuery, SpatialRef, list_crs};
///
/// let albers = list_crs(&CrsQuery { text: Some("3577".into()), ..Default::default() });
/// assert_eq!(albers[0].name, "GDA94 / Australian Albers");
/// let crs = SpatialRef::parse(&albers[0].authority_code())?;
/// # Ok::<(), terrio_crs::Error>(())
/// ```
pub fn list_crs(query: &CrsQuery) -> Vec<CrsEntry> {
    let c = catalog();
    let words: Vec<String> = query.text.as_deref().unwrap_or_default().split_whitespace().map(str::to_lowercase).collect();
    c.records
        .iter()
        .filter(|r| query.include_deprecated || !r.deprecated)
        .filter(|r| query.kinds.is_empty() || query.kinds.contains(&r.kind))
        .filter(|r| query.authorities.is_empty() || query.authorities.iter().any(|a| a.trim().eq_ignore_ascii_case(r.authority)))
        .filter(|r| r.matches(&words) && r.resolves())
        .map(|r| r.entry(c))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::SpatialRef;

    fn all() -> Vec<CrsEntry> {
        list_crs(&CrsQuery { include_deprecated: true, ..Default::default() })
    }

    #[test]
    fn finds_australian_albers_by_name_and_code() {
        for text in ["Albers", "3577", "EPSG:3577", "epsg:3577", "gda94 ALBERS", "epsg albers", "EPSG: 3577"] {
            let found = list_crs(&CrsQuery { text: Some(text.into()), ..Default::default() });
            let e = found.iter().find(|e| e.authority == "EPSG" && e.code == 3577).unwrap_or_else(|| panic!("{text}"));
            assert_eq!(e.name, "GDA94 / Australian Albers");
            assert_eq!(e.kind, CrsKind::Projected);
            assert!(!e.deprecated);
            assert_eq!(e.projection_method.as_deref(), Some("Albers Equal Area"));
            assert_eq!(e.celestial_body.as_deref(), Some("Earth"));
            assert_eq!(e.bounds, Some([112.85, -43.7, 153.69, -9.86]));
            assert!(e.area_name.as_deref().is_some_and(|a| a.starts_with("Australia - Australian Capital Territory")));
            assert_eq!(e.authority_code(), "EPSG:3577");
        }
        // Every word must match the same CRS: "gda94" is in EPSG:3577's name, "EPSG:3857" is not.
        let partial = list_crs(&CrsQuery { text: Some("gda94 EPSG:3857".into()), ..Default::default() });
        assert!(!partial.iter().any(|e| e.authority == "EPSG" && e.code == 3577));
        // A word must begin the code: 13577 is not EPSG:3577, nor is ESRI:3577 (no such CRS).
        let found = list_crs(&CrsQuery { text: Some("ESRI:3577".into()), ..Default::default() });
        assert!(found.is_empty());
    }

    /// Every listed CRS resolves, by its authority's constructor and by `SpatialRef::parse`.
    #[test]
    fn every_listed_crs_resolves() {
        let entries = all();
        for e in &entries {
            let resolved = match e.authority {
                "EPSG" => SpatialRef::from_epsg(e.code),
                "ESRI" => SpatialRef::from_esri(e.code),
                "IAU_2015" => SpatialRef::from_iau(e.code),
                other => panic!("unexpected authority {other}"),
            };
            assert!(resolved.is_ok(), "{}: {:?}", e.authority_code(), resolved.err());
        }
        // `parse` on a sample (it identifies the WKT of each, which takes longer).
        for e in entries.iter().step_by(97) {
            assert!(SpatialRef::parse(&e.authority_code()).is_ok(), "{}", e.authority_code());
        }
    }

    /// The catalog's names are those of terrio's EPSG table, so the list describes the CRS the
    /// code resolves to.
    #[test]
    fn names_match_the_epsg_table() {
        for e in all().iter().filter(|e| e.authority == "EPSG") {
            let name = crate::epsg::get(e.code)
                .map(|c| c.name.as_str())
                .or_else(|| crate::epsg::vertical(e.code).map(|v| v.name.as_str()))
                .or_else(|| crate::epsg::compound(e.code).map(|c| c.name.as_str()));
            assert_eq!(name, Some(e.name.as_str()), "EPSG:{}", e.code);
        }
    }

    #[test]
    fn counts_by_authority_and_kind() {
        let entries = all();
        let count = |auth: &str, kind: Option<CrsKind>, deprecated: Option<bool>| {
            entries
                .iter()
                .filter(|e| e.authority == auth && kind.is_none_or(|k| e.kind == k) && deprecated.is_none_or(|d| e.deprecated == d))
                .count()
        };
        // PROJ 9.8.1's database has 7741 EPSG CRSs; terrio's table resolves all but the
        // engineering CRSs and other compound CRSs.
        assert_eq!(count("EPSG", None, None), 7681);
        assert_eq!(count("EPSG", Some(CrsKind::Geographic2D), None), 689);
        assert_eq!(count("EPSG", Some(CrsKind::Geographic3D), None), 273);
        assert_eq!(count("EPSG", Some(CrsKind::Geocentric), None), 269);
        assert_eq!(count("EPSG", Some(CrsKind::Projected), None), 5680);
        assert_eq!(count("EPSG", Some(CrsKind::Vertical), None), 299);
        assert_eq!(count("EPSG", Some(CrsKind::Compound), None), 471);
        assert_eq!(count("EPSG", None, Some(true)), 520);
        // 2528 in the catalog, less those on projections terrio does not compute: Wagner VII,
        // Compact Miller, Goode Homolosine Ocean, Peirce quincuncial and Spilhaus; and without
        // wbprojection, the 32 on Eckert, Aitoff, Natural Earth and other projections.
        let refused = if cfg!(feature = "wbprojection-fallback") { 9 } else { 41 };
        assert_eq!(count("ESRI", None, None), 2528 - refused);
        assert_eq!(count("IAU_2015", None, None), 2201);
        assert_eq!(count("IAU_2015", Some(CrsKind::Other), None), 12);
        // The default leaves deprecated CRSs out.
        let current = list_crs(&CrsQuery::default());
        assert_eq!(current.len(), entries.iter().filter(|e| !e.deprecated).count());
        assert!(current.iter().all(|e| !e.deprecated));
    }

    #[test]
    fn filters_by_authority_kind_and_deprecation() {
        let geographic = list_crs(&CrsQuery {
            authorities: vec!["epsg".into()],
            kinds: vec![CrsKind::Geographic2D, CrsKind::Projected],
            ..Default::default()
        });
        assert!(geographic.iter().all(|e| e.authority == "EPSG" && matches!(e.kind, CrsKind::Geographic2D | CrsKind::Projected)));
        assert!(geographic.iter().any(|e| e.code == 4326) && geographic.iter().any(|e| e.code == 3857));
        // EPSG:4326 is not deprecated; EPSG:3785 (Popular Visualisation CRS / Mercator) is.
        assert!(geographic.iter().all(|e| e.code != 3785));
        let with = list_crs(&CrsQuery { text: Some("3785".into()), include_deprecated: true, ..Default::default() });
        assert!(with.iter().any(|e| e.code == 3785 && e.deprecated));
        assert!(list_crs(&CrsQuery { authorities: vec!["OGC".into()], ..Default::default() }).is_empty());
        // In order of authority, then code.
        let order: Vec<(usize, u32)> =
            all().iter().map(|e| (AUTHORITIES.iter().position(|a| *a == e.authority).unwrap(), e.code)).collect();
        assert!(order.is_sorted());
        let esri = list_crs(&CrsQuery { text: Some("contiguous albers".into()), authorities: vec!["ESRI".into()], ..Default::default() });
        assert!(esri.iter().any(|e| e.code == 102003));
        let mars = list_crs(&CrsQuery { authorities: vec!["IAU_2015".into()], text: Some("49902".into()), ..Default::default() });
        assert_eq!(mars.len(), 1);
        assert_eq!((mars[0].kind, mars[0].celestial_body.as_deref()), (CrsKind::Other, Some("Mars")));
    }

    #[test]
    fn checks_authorities_whatever_their_case() {
        assert!(check_authorities(&[]).is_ok());
        assert!(check_authorities(&["epsg".into(), " ESRI ".into(), "IAU_2015".into()]).is_ok());
        let err = check_authorities(&["EPSG".into(), "OGC".into()]).unwrap_err();
        assert!(err.to_string().contains("unknown CRS authority \"OGC\""), "{err}");
    }

    #[test]
    fn texts_are_unescaped() {
        assert_eq!(unescape(r"a\tb\nc\\d\re"), "a\tb\nc\\d\re");
        assert_eq!(unescape("plain"), "plain");
        // EPSG:32075's area name ends with a line feed in PROJ's database, as GDAL gives it.
        let e = list_crs(&CrsQuery { text: Some("EPSG:32075".into()), include_deprecated: true, ..Default::default() });
        assert!(e[0].area_name.as_deref().is_some_and(|a| a.ends_with("Amery Terrace.\n")), "{:?}", e[0].area_name);
    }

    #[test]
    fn kinds_parse_from_their_names() {
        for kind in CrsKind::ALL {
            assert_eq!(kind.as_str().parse::<CrsKind>().unwrap(), kind);
            assert_eq!(serde_json::to_value(kind).unwrap(), kind.as_str());
        }
        assert_eq!("Geographic_2D".parse::<CrsKind>().unwrap(), CrsKind::Geographic2D);
        assert!("geographic".parse::<CrsKind>().is_err());
    }

    /// The version documented in [`EPSG_VERSION`] is the catalog's.
    #[test]
    fn epsg_version_is_the_catalogs() {
        let text = crate::epsg::decompress(DATA);
        assert!(text.lines().any(|l| l == format!("#\tEPSG\t{EPSG_VERSION}\t2025-10-02")), "{}", &text[..300]);
    }
}
